class SecureAccount:
    def __init__(self, balance):
        self.__balance = balance  # 私有属性

    @property
    def balance(self):
        return self.__balance

    @balance.setter
    def balance(self, value):
        if value < 0:
            raise ValueError('余额不能设置为负数!')
        self.__balance = value

acc = SecureAccount(1000)
acc.balance = 1500  # 自动触发 setter 校验
print(f'受保护余额: {acc.balance}')

class Account:
    def __init__(self, owner, balance):
        self.owner = owner
        self.balance = balance

class SavingsAccount(Account):
    def __init__(self, owner, balance, interest_rate=0.03):
        super().__init__(owner, balance)
        self.interest_rate = interest_rate

    def add_interest(self):
        interest = self.balance * self.interest_rate
        self.balance += interest
        print(f'利息结算完成 +{interest}元，最新余额: {self.balance}')

s = SavingsAccount('王五', 10000)
s.add_interest()

